-- inspection export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from inspections i cross join bounds where i.organization_id = $5 and i.deleted_at is null and i.is_wet = $6 and i.density = any($7::larval_density[]) and coalesce( i.is_wet and (i.density <> 'none' or i.larvae_count > 0), false ) and i.habitat_type_id = any($8::uuid[]) and i.inspected_by_profile_id = any($9::uuid[]) and i.inspection_date >= $10 and i.inspection_date <= $11 and exists ( select 1 from regions rf where rf.id = any($12::uuid[]) and rf.organization_id = i.organization_id and rf.deleted_at is null and rf.geom && i.geom and case when i.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(i.geom) then i.geom else st_collectionextract(st_makevalid(i.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, i.geom) end ) and i.geom && bounds.geom_4326 and st_intersects(i.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select i.inspection_date::text as "c0", h.habitat_name as "c1", ht.name as "c2", a.display_name as "c3", p.display_name as "c4", case when i.is_wet then 'Yes' when not i.is_wet then 'No' end as "c5", i.dip_count as "c6", (upper(left(replace(i.density::text, '_', ' '), 1)) || substr(replace(i.density::text, '_', ' '), 2)) as "c7", i.larvae_count as "c8", case when i.has_eggs then 'Yes' when not i.has_eggs then 'No' end as "c9", case when i.has_first_instar then 'Yes' when not i.has_first_instar then 'No' end as "c10", case when i.has_second_instar then 'Yes' when not i.has_second_instar then 'No' end as "c11", case when i.has_third_instar then 'Yes' when not i.has_third_instar then 'No' end as "c12", case when i.has_fourth_instar then 'Yes' when not i.has_fourth_instar then 'No' end as "c13", case when i.has_pupae then 'Yes' when not i.has_pupae then 'No' end as "c14", case when coalesce( i.is_wet and (i.density <> 'none' or i.larvae_count > 0), false ) then 'Yes' when not coalesce( i.is_wet and (i.density <> 'none' or i.larvae_count > 0), false ) then 'No' end as "c15", i.lat as "c16", i.lng as "c17", to_char(i.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c18", to_char(i.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c19" from inspections i left join habitats h on h.id = i.habitat_id left join addresses a on a.id = i.address_id left join profiles p on p.id = i.inspected_by_profile_id left join habitat_types ht on ht.id = i.habitat_type_id cross join bounds where i.organization_id = $7 and i.deleted_at is null and i.is_wet = $8 and i.density = any($9::larval_density[]) and coalesce( i.is_wet and (i.density <> 'none' or i.larvae_count > 0), false ) and i.habitat_type_id = any($10::uuid[]) and i.inspected_by_profile_id = any($11::uuid[]) and i.inspection_date >= $12 and i.inspection_date <= $13 and exists ( select 1 from regions rf where rf.id = any($14::uuid[]) and rf.organization_id = i.organization_id and rf.deleted_at is null and rf.geom && i.geom and case when i.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(i.geom) then i.geom else st_collectionextract(st_makevalid(i.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, i.geom) end ) and i.geom && bounds.geom_4326 and st_intersects(i.geom, bounds.geom_4326) order by i.inspection_date desc, i.created_at desc, i.id